param([string]$OutputDirectory='Architecture/M182_Pantry_Bypass_Route_Audit_2026-10-31/artifacts')
$ErrorActionPreference='Stop'
$root=Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path);$out=Join-Path $root $OutputDirectory
$bathRel='Architecture/Direction_D_BathFirst_Adjacency_Study_2026-10-27/study.json';$m181Rel='Architecture/M181_All_Room_Interface_Audit_2026-10-31/artifacts/m181-study.json';$selectedRel='Architecture/Selected_Design_Iteration_2026-10-27/study.json';$m173Rel='Architecture/Direction_D_Social_Route_Study_2026-10-27/study.json'
foreach($r in @($bathRel,$m181Rel,$selectedRel,$m173Rel)){if(-not(Test-Path (Join-Path $root $r) -PathType Leaf)){throw "Missing input $r"}}
if((Test-Path $out)-and @(Get-ChildItem $out -Force).Count-gt0){throw "Refusing to overwrite $out"};if(-not(Test-Path $out)){New-Item -ItemType Directory $out|Out-Null}
function Sha182($p){(Get-FileHash (Join-Path $root $p) -Algorithm SHA256).Hash.ToLowerInvariant()}
$bath=Get-Content (Join-Path $root $bathRel) -Raw|ConvertFrom-Json;$m181=Get-Content (Join-Path $root $m181Rel) -Raw|ConvertFrom-Json;$m173=Get-Content (Join-Path $root $m173Rel) -Raw|ConvertFrom-Json;$main=$bath.plans.main
$m01=@($main|Where-Object id -eq 'M-01')[0];$m02=@($main|Where-Object id -eq 'M-02')[0];$m03=@($main|Where-Object id -eq 'M-03')[0];$m04=@($main|Where-Object id -eq 'M-04')[0];$m05=@($main|Where-Object id -eq 'M-05')[0];$ox=[double]$m02.x;$oy=[double]$m02.y;$shellW=[double]$bath.selection.main_shell[0];$shellD=[double]$bath.selection.main_shell[1]
$blocks=@{};foreach($b in @($m01,$m02,$m03,$m04,$m05)){$blocks[$b.id]=[ordered]@{id=$b.id;x=([double]$b.x-$ox);y=([double]$b.y-$oy);w=[double]$b.w;d=[double]$b.d}}
$windows=@();foreach($w in $bath.selection.main_public_bath.search_windows){$windows+=,[ordered]@{id=$w.id;x=([double]$w.x-$ox);y=([double]$w.y-$oy);w=[double]$w.w;d=[double]$w.d;status=[string]$w.status}};$windowA=@($windows|Where-Object id -eq 'west_of_core')[0];$windowB=@($windows|Where-Object id -eq 'east_of_core')[0]
$path=@([pscustomobject]@{x=19.5;y=10.0},[pscustomobject]@{x=18.6666666667;y=10.0},[pscustomobject]@{x=18.6666666667;y=27.5},[pscustomobject]@{x=8.5;y=27.5},[pscustomobject]@{x=8.5;y=30.5})
function Rects182($p,$width){$rs=New-Object System.Collections.Generic.List[object];for($i=0;$i-lt$p.Count-1;$i++){$a=$p[$i];$b=$p[$i+1];if([Math]::Abs($a.x-$b.x)-lt1e-6){$rs.Add([ordered]@{id="segment-$i";x=$a.x-$width/2;y=[Math]::Min($a.y,$b.y);w=$width;d=[Math]::Abs($b.y-$a.y)})}else{$rs.Add([ordered]@{id="segment-$i";x=[Math]::Min($a.x,$b.x);y=$a.y-$width/2;w=[Math]::Abs($b.x-$a.x);d=$width})};if($i-gt0){$rs.Add([ordered]@{id="corner-$i";x=$a.x-$width/2;y=$a.y-$width/2;w=$width;d=$width})}};return $rs.ToArray()}
function Hit182($a,$b){$dx=[Math]::Min($a.x+$a.w,$b.x+$b.w)-[Math]::Max($a.x,$b.x);$dy=[Math]::Min($a.y+$a.d,$b.y+$b.d)-[Math]::Max($a.y,$b.y);if($dx-gt1e-6-and$dy-gt1e-6){return [ordered]@{route=$a.id;target=$b.id;area_sf=[Math]::Round($dx*$dy,6)}};return $null}
$cabinet=[ordered]@{id='perimeter-cabinet-run';x=0.0;y=0.75;w=2.0;d=12.5};$island=[ordered]@{id='island';x=5.5;y=3.0;w=4.0;d=8.0};$stools=[ordered]@{id='assumed-dining-face-stools';x=5.5;y=11.0;w=4.0;d=2.0};$table=[ordered]@{id='dining-table';x=3.0;y=17.5;w=5.0;d=3.0};$chairs=@([ordered]@{id='south-chair-1';x=3.5;y=15.8333333333;w=1.5;d=1.6666666667},[ordered]@{id='south-chair-2';x=6.0;y=15.8333333333;w=1.5;d=1.6666666667},[ordered]@{id='west-chair-1';x=1.3333333333;y=17.5;w=1.6666666667;d=1.5},[ordered]@{id='west-chair-2';x=1.3333333333;y=19.0;w=1.6666666667;d=1.5})
$walls=@([ordered]@{id='half-wall';x=13.0;y=0.0;w=0.5;d=7.0},[ordered]@{id='wall-return';x=13.0;y=13.0;w=0.5;d=1.0},[ordered]@{id='porch-west-wall';x=-0.5;y=24.5;w=6.5;d=0.5},[ordered]@{id='porch-east-wall';x=11.0;y=24.5;w=0.5;d=0.5})
$obstacles=@($blocks['M-04'])+@($blocks['M-05'])+@($windowB)+@($cabinet)+@($island)+@($stools)+@($table)+@($chairs)+@($walls);$rects=Rects182 $path 3.0;$hits=New-Object System.Collections.Generic.List[object];$westWindowHits=New-Object System.Collections.Generic.List[object];foreach($r in $rects){foreach($o in $obstacles){$h=Hit182 $r $o;if($null-ne$h){$hits.Add($h)}};$wa=Hit182 $r $windowA;if($null-ne$wa){$westWindowHits.Add($wa)}}
$throat=[double]$windowB.x-($blocks['M-04'].x+$blocks['M-04'].w);$routeWest=$path[2].x-1.5;$routeEast=$path[2].x+1.5;$pantryGap=($routeWest-($blocks['M-04'].x+$blocks['M-04'].w))*12;$bathGap=($windowB.x-$routeEast)*12;$corridorWest=$path[2].x-1.5;$candidateM02East=13.5;$sourceM02East=$blocks['M-02'].x+$blocks['M-02'].w;$intrusionM02=($sourceM02East-$corridorWest)*12;$minX=($rects|ForEach-Object{[double]$_.x}|Measure-Object -Minimum).Minimum;$minY=($rects|ForEach-Object{[double]$_.y}|Measure-Object -Minimum).Minimum;$maxX=($rects|ForEach-Object{[double]($_.x+$_.w)}|Measure-Object -Maximum).Maximum;$maxY=($rects|ForEach-Object{[double]($_.y+$_.d)}|Measure-Object -Maximum).Maximum;$routeBounds=[ordered]@{min_x=$minX;min_y=$minY;max_x=$maxX;max_y=$maxY};$porchStartY=27.5;$doorSpan=@(6.0,11.0);$m01Inside=($path[0].x-ge$blocks['M-01'].x-and$path[0].x-le($blocks['M-01'].x+$blocks['M-01'].w)-and$path[0].y-ge$blocks['M-01'].y-and$path[0].y-le($blocks['M-01'].y+$blocks['M-01'].d));$m06BRemains=($m173.geometry.m06_window_b_remains_unassigned-eq$true)
$checks=New-Object System.Collections.Generic.List[object];function Add182($id,$pass,$detail){$script:checks.Add([pscustomobject]@{id=$id;pass=[bool]$pass;detail=$detail})}
Add182 'm181_bound_sources_current' (([string]$m181.source_fingerprints_sha256.PSObject.Properties[$bathRel].Value-eq(Sha182 $bathRel))-and([string]$m181.source_fingerprints_sha256.PSObject.Properties[$selectedRel].Value-eq(Sha182 $selectedRel))) 'M181 source room blocks and selected-D inputs remain current.'
Add182 'living_origin_inside_source_m01' $m01Inside 'Route begins inside the translated M-01 living room block.'
Add182 'route_clears_assigned_static_obstacles' ($hits.Count-eq0) '36-in corridor rectangles have no positive-area intersection with pantry, entry, M-06/B, kitchen/dining furniture or modeled wall segments.'
Add182 'route_uses_blocked_west_search_zone' ($westWindowHits.Count-gt0) 'Path overlaps the already-blocked west M-06 diagnostic search rectangle; it is not available for a bath assignment.'
Add182 'pantry_to_m06b_throat_measured' ([Math]::Abs($throat-3.6666666667)-lt0.001) 'Source pantry east edge to east_of_core M-06/B window is 44 in; the entire gap is otherwise unassigned.'
Add182 'centered_36_in_route_fits_throat' (([Math]::Abs($pantryGap-4)-lt0.001)-and([Math]::Abs($bathGap-4)-lt0.001)) 'Centered corridor leaves 4 in to pantry and 4 in to the unassigned M-06/B window boundary.'
Add182 'm06_b_window_not_occupied' ($routeEast-le$windowB.x) 'Route corridor stays west of the M-06/B candidate window; no fixture, door or approach is assigned.'
Add182 'south_living_transition_identified' (([Math]::Abs(([double]$blocks['M-01'].y+$blocks['M-01'].d)-15)-lt0.001)-and([Math]::Abs(([double]$blocks['M-04'].y)-16.5)-lt0.001)) 'Path leaves M-01 at its y=15 ft south edge and uses the y=15 to16.5 unassigned band; no opening is in source geometry.'
Add182 'candidate_source_kitchen_residual_quantified' (([Math]::Abs($sourceM02East-17.3333333333)-lt0.001)-and([Math]::Abs($corridorWest-17.1666666667)-lt0.001)-and([Math]::Abs($intrusionM02-2)-lt0.001)-and([Math]::Abs($corridorWest-$candidateM02East-3.6666666667)-lt0.001)) 'Route corridor edge is outside the reduced kitchen candidate but intrudes 2 in into the larger M-02 source room block.'
Add182 'nominal_porch_door_crossed_and_entered' (($path[-2].x-ge$doorSpan[0]-and$path[-2].x-le$doorSpan[1]-and$path[-1].y-$porchStartY-eq3)) 'Route crosses the 5 ft nominal porch-door reservation and extends 3 ft beyond its centerline into the porch test area.'
Add182 'route_inside_40x42_test_shell' (($ox+$routeBounds.min_x-ge0)-and($oy+$routeBounds.min_y-ge0)-and($ox+$routeBounds.max_x-le$shellW)-and($oy+$routeBounds.max_y-le$shellD)) 'Full 36-in route rectangle extents remain inside the hypothetical 40 x 42 ft shell.'
Add182 'm06_b_unassigned' $m06BRemains 'M-06/B remains unassigned after this route comparison.'
Add182 'selected_d_unchanged' ((Get-FileHash (Join-Path $root $selectedRel) -Algorithm SHA256).Hash.ToLowerInvariant()-eq'516d6d17e5b6ed6c8ec8cbf7a925cc67c5cc1c0ada194c22ea3fa124e2bb72bb') 'Selected-D source fingerprint remains unchanged.'
$passed=@($checks|Where-Object pass).Count;$status='fail';if($passed-eq$checks.Count){$status='pass'}
$report=[ordered]@{schema='forever-home-m182-pantry-bypass-route-v1';status='unapproved bypass route and unassigned-corridor test';source_fingerprints_sha256=[ordered]@{$bathRel=(Sha182 $bathRel);$m181Rel=(Sha182 $m181Rel);$selectedRel=(Sha182 $selectedRel);$m173Rel=(Sha182 $m173Rel)};route_centerline_local_ft=$path;route_width_in=36;route_rectangles_local_ft=$rects;positive_area_assigned_obstacle_intersections=$hits.ToArray();blocked_west_search_window_intersections=$westWindowHits.ToArray();route_bounds_local_ft=$routeBounds;translated_blocks=$blocks;m06_windows=$windows;pantry_to_m06b_unassigned_throat_in=[Math]::Round($throat*12,3);clearance_to_pantry_in=[Math]::Round($pantryGap,3);clearance_to_m06b_window_in=[Math]::Round($bathGap,3);candidate_kitchen_corridor_west_edge_gap_ft=[Math]::Round($corridorWest-$candidateM02East,4);corridor_intrusion_into_source_M02_in=[Math]::Round($intrusionM02,3);candidate_M181_bottleneck=$m181.revised_route.centerline_local_ft;design_condition='A new, currently undocumented opening/transition at the south edge of M-01 would be required to enter the unassigned passage. This is not present in the source model.';conclusion='This alternative bypasses the kitchen stools and dining table by routing south from living through the 44 in unassigned corridor between pantry and M-06/B, then across the dining room south band to the nominal porch door. It leaves only 4 in to the pantry and 4 in to the M-06/B window proxy and overlaps 4.736 sf of the already-blocked west M-06 search-window rectangle. The route is geometrically possible in the rectangle overlay but is a narrow, unresolved circulation reservation that may constrain half-bath door/approach/service coordination.';limitations=@('Bath-first blocks and all furniture, door and porch rectangles are unapproved coordinate proxies.','The route needs a new opening at the south edge of M-01 and an assigned corridor; neither is documented or modeled.','Four-inch margins do not validate wall finish, construction tolerance, bath door approach/swing, access, or service routing.','The path crosses the already-blocked west bath search rectangle, and its corridor edge extends 2 in into source M-02 outside the reduced kitchen candidate.','No occupant/furniture movement, thresholds, physical walls, door leaf or clear opening are verified.','M-06/B remains unassigned; no Revit/IFC change or code/accessibility/structural/professional/permit/construction approval.')}
$cr=[ordered]@{status=$status;passed=$passed;total=$checks.Count;checks=$checks.ToArray()}
$report|ConvertTo-Json -Depth 80|Set-Content (Join-Path $out 'm182-study.json') -Encoding UTF8;$cr|ConvertTo-Json -Depth 50|Set-Content (Join-Path $out 'm182-checks.json') -Encoding UTF8;$checks.ToArray()|Export-Csv (Join-Path $out 'm182-checks.csv') -NoTypeInformation -Encoding UTF8
Write-Output ("M182: {0}/{1}; obstacle hits={2}; throat={3:F0} in; pantry/B edge margins={4:F0}/{5:F0} in." -f $passed,$checks.Count,$hits.Count,($throat*12),$pantryGap,$bathGap)
if($passed-ne$checks.Count){exit 1}
